using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.Integrations; using OrcaFacil.Application.Security; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Settings.ApiKeys;
[Authorize(Policy="Permission:"+PermissionCodes.ApiKeysManage)] public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current,IApiKeyService keys,IAuditService audit):PageModel { [BindProperty] public string Name{get;set;}=""; [BindProperty] public string[] Scopes{get;set;}=[]; [BindProperty] public DateTime? ExpiresAt{get;set;} public IReadOnlyList<ApiKey> Items{get;private set;}=[]; public string? CreatedKey=>TempData["CreatedApiKey"] as string; public async Task<IActionResult> OnGetAsync(CancellationToken ct){if(!current.AccountId.HasValue)return Forbid();Items=await db.ApiKeys.AsNoTracking().Where(x=>x.AccountId==current.AccountId&&!x.IsDeleted).OrderByDescending(x=>x.CreatedAt).ToListAsync(ct);return Page();} public async Task<IActionResult> OnPostCreateAsync(CancellationToken ct){if(!current.AccountId.HasValue)return Forbid();try{var created=keys.Create(current.AccountId.Value,current.UserId,Name,Scopes,ExpiresAt?.ToUniversalTime());db.ApiKeys.Add(created.Entity);await db.SaveChangesAsync(ct);await audit.RegisterAsync(current.UserId,"api_key.created",nameof(ApiKey),created.Entity.Id.ToString(),null,new{created.Entity.Name,created.Entity.Prefix,created.Entity.Scopes,created.Entity.ExpiresAt},null,ct,current.AccountId);TempData["CreatedApiKey"]=created.PlaintextKey;return RedirectToPage();}catch(ArgumentException e){ModelState.AddModelError(string.Empty,e.Message);return await OnGetAsync(ct);}} public async Task<IActionResult> OnPostRevokeAsync(Guid id,CancellationToken ct){if(!current.AccountId.HasValue)return Forbid();var item=await db.ApiKeys.SingleOrDefaultAsync(x=>x.Id==id&&x.AccountId==current.AccountId&&!x.IsDeleted,ct);if(item is null)return NotFound();item.RevokedAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);await audit.RegisterAsync(current.UserId,"api_key.revoked",nameof(ApiKey),id.ToString(),null,new{item.Prefix},null,ct,current.AccountId);return RedirectToPage();}}
